function restoreEditorFields(fields){for(const saved of fields||[])for(const control of document.querySelectorAll('#sheet-form input,#sheet-form select,#sheet-form textarea,#branding-form input,#branding-form textarea'))if(control.type!=='file'&&control.name===saved.name&&control.type===saved.type){if(['checkbox','radio'].includes(control.type)){if(control.value===saved.value)control.checked=saved.checked;}else control.value=saved.value;}}

