function refreshUserState(){S.users=appUsers.map(publicUser)}
async function loadUsers(){appUsers=await database.all('users');refreshUserState();if(ready)ownerRecovery.register().catch(()=>{})}
async function reloadAfterOwnerRecovery(){
 if(!ownerRecoveryReloadPending)return;
 if(!ownerRecoveryReloadFlight)ownerRecoveryReloadFlight=(async()=>{
  const current=await database.load();if(!current)throw Error('تعذّرت قراءة بيانات المحل بعد الاستعادة. أعد المحاولة دون حذف التطبيق.');
  S=current;await loadUsers();ownerRecoveryReloadPending=false;ownerRecoveryBusy=false;if(ready)render();
 })();
 try{await ownerRecoveryReloadFlight}finally{ownerRecoveryReloadFlight=null;setBusyButtons()}
}

async function makeSession(user,generation){const current=()=>ownerSessionGenerations.get(user.id)||0;if(current()!==generation)throw Error('تغيّرت بيانات الدخول. سجّل الدخول مجددًا بكلمة المرور الحالية.');const token=crypto.randomUUID()+crypto.randomUUID();await database.createSession(user,{id:'session:'+await digest(token),user:user.id,expiresAt:Date.now()+12*60*60*1000});if(current()!==generation)throw Error('تغيّرت بيانات الدخول. سجّل الدخول مجددًا بكلمة المرور الحالية.');sessionStorage.setItem(sessionKey,token);revokedOwnerSessions.delete(user.id);actor=publicUser(user)}
async function readSession(){const token=sessionStorage.getItem(sessionKey);if(!token)return;const row=await database.get('meta','session:'+await digest(token));const user=appUsers.find(u=>u.id===row?.user&&u.active!==false);if(row?.expiresAt>Date.now()&&user&&!revokedOwnerSessions.has(user.id))actor=publicUser(user)}
async function logout(){if(window.NativeFiles?.accountAccess&&accountBootstrap.mode!=='legacy'){await NativeFiles.accountAccess('logout');if(onlineMode)database.clear();actor=null;appUsers=[];cart=[];modal=null;history=[];window.NativeHost?.openAccountAccess();return}savePosDraft();const token=sessionStorage.getItem(sessionKey);if(token)await database.put('meta',{id:'session:'+await digest(token),expiresAt:0});sessionStorage.removeItem(sessionKey);actor=null;modal=null;cart=[];editingId=null;history=[];authMode='login';render()}
