  if(modal==='site-import')return modalMarkup('استعادة نسخة احتياطية',`<label class="backup-file-picker"><span class="backup-file-heading">اختر ملف النسخة</span><small data-backup-file-name>JSON · لم يُحدد ملف</small><input id="backup-file" type="file" accept=".json,application/json" aria-label="اختر ملف النسخة"></label><p class="muted">نسخة الكرنه أو نسخة كونتا أوفلاين الرسمية.</p><details class="paste-backup"><summary>أو لصق نص النسخة</summary><label class="field"><span>نص النسخة JSON</span><textarea id="backup-json" aria-label="نص النسخة JSON" rows="6" dir="ltr" spellcheck="false"></textarea></label></details><p class="notice">لن تُستبدل البيانات قبل عرض ملخص النسخة وتأكيد الاستعادة.</p>${previousRestoreCopy?`<details class="feature-details"><summary>نسخة الأمان السابقة</summary><p class="muted" dir="auto">${esc(new Date(previousRestoreCopy).toLocaleString(localeTag()))}</p><button type="button" class="secondary" data-action="site:previous-backup">حفظ نسخة الأمان في ملف</button></details>`:''}`,'site:review-import','مراجعة النسخة');
