async function saveUser(){const f=form(),old=appUsers.find(u=>u.id===userEdit),username=String(f.username||'').trim().toLowerCase();if(!f.name?.trim()||!username||appUsers.some(u=>u.username===username&&u.id!==old?.id))return fail('أدخل اسمًا واسم مستخدم فريدًا');if(!old&&f.password.length<4||f.password&&f.password.length<4)return fail('كلمة المرور يجب أن تكون 4 أحرف على الأقل');const role=old?.role==='owner'?'owner':f.role;if(!roleNames[role])return fail('اختر صلاحية صحيحة');const user={...old,id:old?.id||crypto.randomUUID(),name:f.name.trim(),username,role,active:old?.id===actor.id?true:f.active!=='false',capabilities:role==='owner'?[...CAPABILITIES]:[...PRESETS[role]],password:f.password?await passwordDigest(f.password):old.password,updatedAt:new Date().toISOString()};await persistUser(user);modal=null;render();toast('تم حفظ المستخدم')}
