function printInvoice(){const r=S.records.find(r=>r.id===selected);if(!r)return;let root=document.querySelector('#print-root');if(!root){root=document.createElement('section');root.id='print-root';root.hidden=true;document.body.append(root)}root.innerHTML=`<h1>${esc(S.branding)}</h1><p>${esc(S.brandInfo?.address||'')} · ${esc(S.brandInfo?.phone||'')}</p><div class="print-meta"><span>${esc(documentLabels[r.kind])} · ${esc(r.number||r.kind.toUpperCase()+'-'+r.id)}</span><span>${esc(r.date)} ${esc(r.time)}</span></div><h2>${esc(r.title)}</h2>${r.voided?'<p>ملغاة</p>':''}<table><thead><tr><th>الرقم</th><th>المنتج / البيان</th><th>الكمية</th><th>سعر الوحدة</th><th>المبلغ</th></tr></thead><tbody>${r.lines.length?r.lines.map((l,i)=>`<tr><td>${i+1}</td><td>${esc(l.name)}</td><td>${formatNumber(l.qty)}</td><td>${formatNumber(l.price)}</td><td>${formatNumber(l.qty*l.price)}</td></tr>`).join(''):`<tr><td>1</td><td>${esc(r.title)}</td><td>1</td><td>${r.total}</td><td>${r.total}</td></tr>`}</tbody></table><p class="total">الإجمالي: ${formatNumber(r.total)} MRU</p><p>${['stocktransfer','adjustment','offset'].includes(r.kind)?'عملية غير نقدية':r.due?'ملاحظة على الحساب — دون حركة نقدية':'دفع مباشر'}</p><p>${esc(r.note||'')}</p><p>${esc(S.brandInfo?.footer||'')}</p>`;translateUi(root);window.print()}
function exportRecords(){return S.records.filter(r=>(filter==='void'?r.voided:!r.voided)&&(view!=='operations'||filter==='all'||filter==='void'||r.kind===filter)&&inPeriod(r)&&(!search||searchMatches(r.title+' '+r.id+' '+r.kind+' '+(documentLabels[r.kind]||'')+' '+(r.number||''),search)))}
